// QTR-8RC: eight RC sensors timed by the Nano
#include <QTRSensors.h>

QTRSensors qtr;
const uint8_t SENSORS[8] = {A0, A1, A2, A3, A4, A5, 11, 12};   // OUT1-OUT8: any digital pin can time an RC output
uint16_t values[8];
const int PWMA = 5, AIN1 = 7, AIN2 = 8, STBY = 9, BIN1 = 10, BIN2 = 4, PWMB = 6;
const int BASE = 150;

void motors(int left, int right) {   // both wheels forward, speed from 0 to 255
  digitalWrite(AIN1, HIGH); digitalWrite(AIN2, LOW); analogWrite(PWMA, constrain(left, 0, 255));
  digitalWrite(BIN1, HIGH); digitalWrite(BIN2, LOW); analogWrite(PWMB, constrain(right, 0, 255));
}

void setup() {
  Serial.begin(9600);
  qtr.setTypeRC();
  qtr.setSensorPins(SENSORS, 8);
  qtr.setEmitterPin(2);          // LEDON: the library turns the IR LEDs on for each read
  for (int p = 4; p <= 10; p++) pinMode(p, OUTPUT);
  digitalWrite(STBY, HIGH);
  for (int i = 0; i < 100; i++) {   // sweep the array over the tape now: each sensor learns its own white and black
    qtr.calibrate();
    delay(20);
  }
  Serial.println("follow: Kp 0.05, base 150");
}

void loop() {
  uint16_t pos = qtr.readLineBlack(values);
  int error = (int)pos - 3500;   // how far the line is from the centre: negative = left
  int turn = error / 20;         // Kp = 0.05: 2500 off centre changes each wheel by 125
  motors(BASE + turn, BASE - turn);
  Serial.print("pos ");
  Serial.print(pos);
  Serial.print(" L ");
  Serial.print(constrain(BASE + turn, 0, 255));
  Serial.print(" R ");
  Serial.println(constrain(BASE - turn, 0, 255));
  delay(1000);
}

// QTR-8RC: eight RC sensors timed by the Nano
#include <QTRSensors.h>

QTRSensors qtr;
const uint8_t SENSORS[8] = {A0, A1, A2, A3, A4, A5, 11, 12};   // OUT1-OUT8: any digital pin can time an RC output
uint16_t values[8];

void setup() {
  Serial.begin(9600);
  qtr.setTypeRC();
  qtr.setSensorPins(SENSORS, 8);
  qtr.setEmitterPin(2);          // LEDON: the library turns the IR LEDs on for each read
  for (int i = 0; i < 100; i++) {   // sweep the array over the tape now: each sensor learns its own white and black
    qtr.calibrate();
    delay(20);
  }
  Serial.println("calibrated: position 0-7000");
}

void loop() {
  uint16_t pos = qtr.readLineBlack(values);   // 0 = the line under sensor 1, 3500 = centre, 7000 = under sensor 8
  Serial.print("position ");
  Serial.println(pos);
  delay(1000);
}

// QTR-8RC: eight RC sensors timed by the Nano
#include <QTRSensors.h>

QTRSensors qtr;
const uint8_t SENSORS[8] = {A0, A1, A2, A3, A4, A5, 11, 12};   // OUT1-OUT8: any digital pin can time an RC output
uint16_t values[8];

void setup() {
  Serial.begin(9600);
  qtr.setTypeRC();
  qtr.setSensorPins(SENSORS, 8);
  qtr.setEmitterPin(2);          // LEDON: the library turns the IR LEDs on for each read
  Serial.println("raw: OUT1-OUT8 in us, 2500 = timeout");
}

void loop() {
  qtr.read(values);              // eight fall times in µs: about 120 over white, 2500 (the timeout) over black
  for (int i = 0; i < 8; i++) {
    if (i > 0) Serial.print(' ');
    Serial.print(values[i]);
  }
  Serial.println();
  delay(1000);
}
